└──────────────────────────────────────────────────────────┘`,stepByStep:[{line:"// Read problem, ask 3+ clarifying questions",explanation:"Understand before solving",memoryChange:"Problem scope defined",output:"Clear understanding"},{line:"// Write code, narrate thought process",explanation:"Code while explaining your reasoning",memoryChange:"Solution taking shape",output:"Working code"},{line:"// Test with examples + edge cases",explanation:"Verify correctness",memoryChange:"Bugs found and fixed",output:"Correct solution"}],code:`// Mock Interview Self-Assessment Checklist:
